        schema: 'public',
      },
      auth: {
        autoRefreshToken: false,
        persistSession: false,
        detectSessionInUrl: false,
      },
      global: {
        fetch: createSupabaseFetch(fetchImpl, timeoutMs, runtime),
      },
    })

